        "items": [
          {
            "title": "Foundations",
            "description": "Monday · 8:00 AM · 45 minutes"
          },
          {
            "title": "Build & progress",
            "description": "Wednesday · 12:00 PM · 60 minutes"
          },
          {
            "title": "Weekend session",
            "description": "Saturday · 9:00 AM · 90 minutes"
          }
